import {managementPanel} from './management.js';
import {DAILY_QUESTS,daily,dayKey} from './progression.js';
const safeId=id=>String(id).replace(/[^a-f0-9]/g,'');
export const imageCache=new Map();
export function customImage(skin){if(!/^custom-[a-f0-9]{24}$/.test(skin))return null;if(!imageCache.has(skin)){const image=new Image();image.src='/skins/'+skin.slice(7)+'.webp';imageCache.set(skin,image)}const im=imageCache.get(skin);return im.complete&&im.naturalWidth?im:null}
export function recoveryView(code,esc){return `<div class="notice warn">Bu yeni kurtarma kodunu güvenli bir yere kaydet. Parolanı unutursan hesabını açar. Önceki kod geçersiz oldu. Kimseyle paylaşma.</div><label>Kurtarma kodun<textarea readonly rows="3">${esc(code)}</textarea></label><button class="primary" data-page="auth">Giriş ekranına dön</button>`}
export async function featurePage(page,params,c){const {S,esc,fmt,form,input,api,empty,modeNotice}=c,p=S.profile;
 if(page==='market'){if(!S.online)return `<h2>Oyuncu Pazarı</h2>${modeNotice()}<p>Premium günleri ve rekor sahipliği, çevrimiçi oyuncular arasında Gold ile devredilir. Başka oyunculara bağlı olmayan antrenmanda ilan verilmez.</p><div class="notice">Çok oyunculu sunucudaki pazar: emanet Premium, tek alıcı, %2 işlem kesintisi ve iptal/iade.</div>`;const m=await api('market');return `<h2>Oyuncu Pazarı</h2><p class="doc">Oyun içi Gold ile Premium günü veya rekor sahipliği al. Rekorun asıl oyuncu adı ve skoru korunur. Satıcıya %2 kesinti sonrası Gold aktarılır. İlan verilen Premium günleri satış tamamlanana veya iptal edilene kadar emanet tutulur.</p>${m.listings.length?m.listings.map(l=>`<div class="list-row"><div><b>${l.kind==='premium'?l.days+' gün Premium':'Rekor #'+l.record_id}</b><small>Satıcı #${l.seller}${l.kind==='record'?' · '+esc(l.record_name)+' · '+fmt(l.score)+' skor':''}</small></div><strong>${fmt(l.price)} Gold</strong>${p?`<button class="primary" data-act="${l.seller===p.id?'marketCancel':'marketBuy'}" data-target="${l.id}">${l.seller===p.id?'İptal / İade':'Satın al'}</button>`:''}</div>`).join(''):empty('Henüz etkin ilan yok.')} ${p?`<div class="profile-columns"><section class="sub-card"><h3>Premium sat</h3>${form('marketList','<input type="hidden" name="kind" value="premium">'+input('Gün (1-30)','days','number','1','required min="1" max="30"')+input('Fiyat · Gold','price','number','20000','required min="500" max="100000000"'),'Premium’u emanete al ve ilan ver')}</section><section class="sub-card"><h3>Rekor sat</h3>${m.ownRecords.length?form('marketList','<input type="hidden" name="kind" value="record"><label>Rekor<select name="record">'+m.ownRecords.map(r=>`<option value="${r.id}">#${r.id} · ${esc(r.room)} · ${fmt(r.score)}</option>`).join('')+'</select></label>'+input('Fiyat · Gold','price','number','10000','required min="500" max="100000000"'),'Rekoru satışa koy'):empty('Sahip olduğun rekor yok.')}</section></div><h3>İşlem geçmişim</h3>${m.history.map(t=>`<div class="list-row"><span>İlan #${t.listing_id} · ${t.buyer===p.id?'Alım':'Satış'}</span><b>${fmt(t.price)} Gold</b><small>Kesinti ${fmt(t.fee)}</small></div>`).join('')||empty('Henüz işlem yok.')}`:'<button class="primary" data-page="auth">İşlem için giriş yap</button>'}`}
 if(page==='security'){if(!S.online||!p)return '<h2>Hesap güvenliği</h2>'+modeNotice()+'<p>Güvenlik işlemleri çevrimiçi hesabınla açılır.</p>';const cap=await api('capabilities');return `<h2>Hesap güvenliği</h2><div class="profile-columns"><section class="sub-card"><h3>Parolanı değiştir</h3>${form('password-change',input('Şimdiki parola','password','password','','required autocomplete="current-password"')+input('Yeni parola','newPassword','password','','required minlength="10" maxlength="128" autocomplete="new-password"'),'Parolayı değiştir ve oturumları kapat','data-security="true"')}</section><section class="sub-card"><h3>Kurtarma kodunu yenile</h3><p>Eski kod geçersiz olur. Yeni kod yalnızca bir kez gösterilir.</p>${form('recovery-code',input('Şimdiki parola','password','password','','required autocomplete="current-password"'),'Yeni kod oluştur','data-security="true"')}</section></div><h3>E-posta durumu</h3><p>${p.emailVerified?'Doğrulandı ✓':cap.mail?'Henüz doğrulanmadı.':'E-posta gönderim hizmeti sunucuda henüz bağlanmadı. Kurtarma koduyla hesabını geri alabilirsin.'}</p>${!p.emailVerified&&cap.mail?form('verify-send','','Doğrulama bağlantısı gönder','data-security="true"'):''}<h3>Hareketlerim</h3>${(await api('ledger')).map(l=>`<div class="list-row"><span>${esc(l.reason)}</span><span>Gold ${l.gold_delta>0?'+':''}${fmt(l.gold_delta)} · Bonus ${l.bonus_delta>0?'+':''}${fmt(l.bonus_delta)}</span><small>${new Date(l.at).toLocaleString('tr-TR')}</small></div>`).join('')||empty('Henüz hesap işlemi yok.')}`}
 if(page==='recover'){if(!S.online)return '<h2>Hesabını kurtar</h2>'+modeNotice()+'<p>Bu bağlantıda şifreli hesap bulunmaz.</p>';const cap=await api('capabilities');return `<h2>Hesabını kurtar</h2><p>Kayıt sırasında kaydettiğin tek kullanımlık kurtarma kodunu kullan. Başarılı işlemde tüm oturumlar kapanır ve yeni kod verilir.</p>${form('recover',input('E-posta','email','email','','required autocomplete="username"')+input('Kurtarma kodu','code','text','','required autocomplete="off"')+input('Yeni parola','newPassword','password','','required minlength="10" maxlength="128" autocomplete="new-password"'),'Hesabı kurtar','data-security="true"')}${cap.mail?'<h3>E-posta ile yenile</h3>'+form('forgot',input('E-posta','email','email','','required'),'Yenileme bağlantısı gönder','data-security="true"'):'<div class="notice">E-posta gönderimi henüz bağlı değil. Kurtarma kodun da yoksa sunucu yöneticisiyle iletişime geç.</div>'}`}
 if(page==='daily'){if(!p)return empty('Önce giriş yap.');const d=daily(p);return modeNotice()+`<h2>Günlük Görevler</h2><p>Türkiye saatiyle 00.00’da yenilenir. Bugün: ${d.day}</p><button class="primary" data-act="dailyLogin" ${p.loginDay===dayKey()?'disabled':''}>${p.loginDay===dayKey()?'Giriş ödülü toplandı':'Giriş ödülünü al · '+(p.premiumUntil>Date.now()?'10.000':'5.000')+' Bonus'}</button>${DAILY_QUESTS.map(q=>`<div class="quest"><div><strong>${q.name}</strong><progress max="${q.target}" value="${d[q.id]}"></progress><small>${fmt(d[q.id])}/${fmt(q.target)} · ${fmt(q.gold)} Gold + ${q.xp} XP</small></div><button class="primary" data-act="claimDaily" data-value="${q.id}" ${d[q.id]<q.target||d.claimed.includes(q.id)?'disabled':''}>${d.claimed.includes(q.id)?'Toplandı':'Topla'}</button></div>`).join('')}<button class="soft" data-page="season">Sezona dön</button>`}
 if(page==='referral'){if(!p)return empty('Önce giriş yap.');return modeNotice()+`<h2>Arkadaşını davet et</h2><p>Davet bağlantınla yeni hesap açan arkadaşın 10 dakika oynayınca ikinize de 10.000 Bonus verilir. Her yeni hesap yalnızca bir kez ödül verir.</p>${S.online?`<label>Davet bağlantın<input readonly value="${esc(location.origin+'/?ref='+p.id)}"></label><p>Senin davet durumun: ${p.referrer?'Davet eden #'+p.referrer+(p.referralRewarded?' · Ödül verildi':' · 10 dakika oynama bekleniyor'):'Bu hesap davet ile açılmadı.'}</p>`:'<p>Antrenman profili için davet bağlantısı üretilmez.</p>'}`}
 if(page==='player'){const a=S.online?await api('profile/'+Number(params.id)):p;if(!a)return empty('Oyuncu bulunamadı');return `<div class="profile-hero"><div class="avatar">${esc(a.name[0])}</div><div><small>HESAP #${a.id}</small><h2>${esc(a.name)}</h2><p>${fmt(a.wins)} galibiyet · Klan ${a.clanId||'Yok'}</p></div></div><p class="doc">${esc(a.bio||'Henüz açıklama yok.')}</p>${p&&a.id!==p.id?`<button class="primary" data-act="follow" data-target="${a.id}">${p.following.includes(a.id)?'Takibi bırak':'Takip et'}</button> <button class="danger" data-act="block" data-target="${a.id}">${p.blocked?.includes(a.id)?'Engeli kaldır':'Mesaj engelle'}</button><h3>Mesaj gönder</h3>${form('message','<input type="hidden" name="target" value="'+a.id+'"><label>Mesaj<textarea name="value" required maxlength="500"></textarea></label>','Gönder')}<h3>Oyuncuyu şikayet et</h3>${form('report','<input type="hidden" name="target" value="'+a.id+'"><label>Açıklama<textarea name="value" required minlength="10" maxlength="500"></textarea></label>','Şikayeti yönetime gönder')}`:''}`}
 if(page==='admin'){if(!S.online||!p)return empty('Önce kendi hesabına giriş yap.');if(!p.isAdmin){const status=await api('management-status');return status.setupAvailable?'<h2>Yönetici kurulumu</h2><p>Özel kurulum kodunu gir. Bu işlem yalnızca bir hesap için yapılabilir.</p>'+form('adminSetup',input('Özel kurulum kodu','code','password','','required autocomplete="off"'),'Bu hesabı yönetici yap','data-management-setup="true"'):empty('Bu hesap yönetici değil.');}const a=await api('admin');return `${await managementPanel(c)}<h3>Destek talepleri</h3>${a.tickets.map(t=>`<section class="sub-card"><small>#${t.id} · Hesap #${t.account_id}</small><h3>${esc(t.title)}</h3><p>${esc(t.text)}</p>${t.replies.map(r=>`<p>#${r.author}: ${esc(r.text)}</p>`).join('')}${form('ticketReply','<input name="target" type="hidden" value="'+t.id+'">'+input('Yanıt','value','text','','required minlength="2" maxlength="500"'),'Yanıtla')}<div class="account-links">${['Açık','İnceleniyor','Çözüldü'].map(status=>`<button data-act="adminTicket" data-target="${t.id}" data-value="${status}">${status===t.status?'✓ ':''}${status}</button>`).join('')}</div></section>`).join('')||empty('Talep yok.')}<h3>Skin denetimi</h3><div class="skin-grid">${a.uploads.map(u=>`<article class="skin-card"><img width="128" height="128" src="/skins/${safeId(u.id)}.webp" alt="Yüklenen skin"><small>Hesap #${u.account_id} · ${esc(u.status)}</small><button class="primary" data-act="adminUpload" data-target="${u.id}" data-value="approved">Onayla</button><button class="danger" data-act="adminUpload" data-target="${u.id}" data-value="rejected">Reddet</button></article>`).join('')}</div><h3>Hesap erişimi</h3>${form('adminBan',input('Hesap no','target','number','','required min="1"')+input('Saat (0 = kısıtlamayı kaldır)','hours','number','24','required min="0" max="8760"'),'Uygula')}<h3>İşlem denetimi</h3>${a.audit.map(l=>`<div class="list-row"><span>#${l.actor} · ${esc(l.action)} → #${l.target}</span><small>${esc(l.detail)}</small></div>`).join('')}`}
 return null}
export async function uploadPanel(c){const {S,api,form,empty,esc}=c;if(!S.online)return '<div class="notice">Özel görsel yükleme çevrimiçi hesapla açılır.</div>';const list=await api('my-uploads');return `<h3>Özel skin yükle</h3><p>PNG / JPEG / WebP, en fazla 256 KB ve 4 milyon piksel. Görseller 256×256 WebP’ye dönüştürülür, yönetici onayından sonra kullanılır.</p><form id="upload-skin" class="form-grid"><label>Görsel<input type="file" name="image" required accept="image/png,image/jpeg,image/webp"></label><button class="primary">Onaya gönder</button></form><div class="skin-grid">${list.map(u=>`<article class="skin-card"><img width="128" height="128" src="/skins/${safeId(u.id)}.webp" alt="Özel skin"><small>${esc(({pending:'Onay bekliyor',approved:'Onaylandı',rejected:'Reddedildi'})[u.status])}</small>${u.status==='approved'?`<button class="primary" data-act="customSkin" data-value="${u.id}">Skinlerime ekle</button>`:''}</article>`).join('')}</div>`}
